'use strict';
const skillOriginalFreePlay=prHome;let skillFreePlay=prInitialView==='playroom';
let skillContext=null;
let skillNotes={};try{const p=JSON.parse(localStorage.getItem('spotmatch-course-notes-v1')||'{}');if(p&&typeof p==='object'&&!Array.isArray(p))skillNotes=p;}catch{}
function skillSave(){try{localStorage.setItem('spotmatch-course-notes-v1',JSON.stringify(skillNotes));}catch{}}
function skillGet(id){return learningSkills.find(s=>s.id===id);}
function skillCourseGet(id){for(const skill of learningSkills){const course=skill.courses.find(c=>c.id===id);if(course)return{skill,course};}throw Error('Unknown course');}
function skillTitle(a){if(a.engine==='playroom')return playroomGames.find(d=>d.id===a.key).title;if(a.engine==='original')return a.key==='visual'?courses[a.index][0]:newCourseInfo[a.key].games[a.index].title;if(a.engine==='support')return supportPathways[a.key].games[a.index].title;return a.engine==='calm'?calmActivities[a.index].title:focusGames[a.index].title;}
function skillArt(a){if(a.engine==='playroom')return prCover(a.key);if(a.engine==='original'){if(a.key==='visual')return art(lessonData(a.index,0).target);if(a.key==='events')return routinePicture(a.index,1);if(a.key==='stories')return storyPicture(a.index,1);return pictureIcon(newCourseInfo[a.key].games[a.index].object||'book');}if(a.engine==='support')return senGameArt(a.key,a.index);if(a.engine==='calm')return calmArt(calmActivities[a.index]);const t=focusMakeTask(a.index,0,0);if(['checklist','collect','missing'].includes(t.mode))return prSvg(`<path d="M0 280H600V360H0Z" fill="#e0e8d2"/>${prObject('basket',26,129,170)}${t.reference.map((p,i)=>`<svg x="${224+i*117}" y="90" width="110" height="150" viewBox="0 0 120 120">${svgBody(focusPicture(p))}</svg>`).join('')}`);if(t.reference.length)return focusPicture(t.reference[0]);return t.options[0]?focusPicture(t.options[0].picture):prCover('map');}
function skillExplored(a,courseId,index){if(skillNotes[courseId]?.activities?.[index])return true;if(a.engine==='playroom')return !!prProgress[a.key]?.explored;if(a.engine==='original')return !!(a.key==='visual'?saved[a.index]?.complete:learningProgress[a.key]?.[a.index]?.complete);if(a.engine==='support')return !!senProgress[a.key]?.[a.index]?.complete;if(a.engine==='calm')return !!calmProgress[a.index]?.explored;return !!focusProgress[a.index]?.explored;}
function skillNav(){document.body.classList.add('pr-simple-navigation');document.querySelector('#libraryNav').textContent='Skills';document.querySelector('#courseNav').textContent='Grown-ups';document.querySelector('#guideNav').hidden=true;document.querySelector('#libraryNav').onclick=skillHome;document.querySelector('#courseNav').onclick=()=>prParents('research');document.querySelector('#brand').onclick=e=>{e.preventDefault();skillHome();};}
function skillHome(){skillFreePlay=false;prLibraryMode=false;prDirectLegacy=false;skillContext=null;if(location.search)history.replaceState(null,'',location.pathname);activeLearningCourse=null;senActive=null;app.innerHTML=`<section class="skill-welcome"><span class="eyebrow">SUPPORT A SKILL. SHARE SOME PLAY.</span><h1>What would you like<br>to help your child develop?</h1><p>Choose a skill to explore guided courses, clear goals, and playful activities.</p><div class="skill-how"><span><b>1</b> Choose a skill</span><span><b>2</b> Find a useful course</span><span><b>3</b> Play & try it in daily life</span></div></section><section class="skill-grid" aria-label="Skills to develop">${learningSkills.map(s=>`<button class="skill-card" data-skill="${s.id}"><div class="skill-card-art" aria-hidden="true">${prCover(s.image)}</div><div><h2>${s.title}</h2><p>${s.question}</p><span>${s.courses.length} guided courses <b aria-hidden="true">→</b></span></div></button>`).join('')}</section><aside class="skill-start-note"><div>${friendlyMascot()}</div><p><b>You do not need a diagnosis to find a starting point.</b><br>Choose an everyday difficulty or an interest. Model, adapt, repeat, or skip. These are supportive educational courses, not treatments or tests.</p><div><button class="back" id="skillHelp">How to use the courses →</button><button class="back" id="skillFreePlay">Just exploring? Open free play →</button></div></aside>`;skillNav();document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>skillDetail(b.dataset.skill));document.querySelector('#skillHelp').onclick=()=>prParents('help');document.querySelector('#skillFreePlay').onclick=()=>{skillFreePlay=true;skillContext=null;prHome();};window.scrollTo(0,0);}
function skillDetail(id){skillFreePlay=false;const s=skillGet(id);skillContext=null;prDirectLegacy=false;app.innerHTML=`<div class="skill-crumb"><button class="back" id="skillBack">← All skills</button><span>CHOOSE A COURSE</span></div><section class="skill-overview"><div><span class="eyebrow">THE SKILL WE CAN SUPPORT</span><h1>${s.title}</h1><p class="skill-lead">${s.goal}</p><p><b>A useful starting point if:</b> ${s.question}</p>${s.id==='attention'?'<p class="micro">Includes ADHD / ADD support. Choose by the child’s observed needs; these games are supplementary practice, not ADHD treatment.</p>':''}</div><div aria-hidden="true">${prCover(s.image)}</div></section><h2 class="skill-section-heading">Which goal fits your child?</h2><section class="skill-course-grid">${s.courses.map(c=>{const done=c.activities.filter((a,i)=>skillExplored(a,c.id,i)).length;return `<button class="skill-course-card" data-skill-course="${c.id}"><span class="eyebrow">${c.level.toUpperCase()}</span><h2>${c.title}</h2><p><b>Our goal:</b> ${c.goal}</p><p class="skill-course-need">${c.need}</p><div class="skill-mini-art" aria-hidden="true">${c.activities.slice(0,3).map(a=>`<span>${skillArt(a)}</span>`).join('')}</div><span class="skill-course-foot">${c.activities.length} activities${done?` · ${done} explored`:''}<b>See the course →</b></span></button>`;}).join('')}</section><p class="skill-small-note">The order is a suggestion, not a developmental assessment. An adult joins in; speech, pointing, signing, and AAC are welcome.</p>`;skillNav();document.querySelector('#skillBack').onclick=skillHome;document.querySelectorAll('[data-skill-course]').forEach(b=>b.onclick=()=>skillCourse(b.dataset.skillCourse));window.scrollTo(0,0);}
function skillEvidenceLinks(skill){let sources=[];if(skill.id==='attention')return focusLinks(['overview','classroom','environment','training']);if(skill.id==='language')sources=supportPathways.language.sources;if(skill.id==='stories')sources=[{title:'Narrative intervention review (2021)',url:newCourseInfo.stories.source,note:'Broader narrative teaching combines explicit instruction, visual supports, and language; our games alone have not been evaluated.'},...supportPathways.language.sources.slice(1)];if(skill.id==='sounds')sources=supportPathways.dyslexia.sources;if(skill.id==='access')sources=[...supportPathways.speech.sources.slice(2),supportPathways.motor.sources[0]];if(skill.id==='everyday')sources=[{title:'ASHA: AAC and meaningful communication access',url:newCourseInfo.meaning.source,note:'AAC has no prerequisites. Picture games do not establish real-world understanding or replace a communication assessment.'}];if(skill.id==='calm')sources=[{title:'NCCIH: Yoga effectiveness and safety',url:'https://www.nccih.nih.gov/health/yoga-effectiveness-and-safety',note:'Adapt movement to the individual. Our short activities are not equivalent to a studied programme.'}];if(skill.id==='seeing')sources=[{title:'Research on discrimination teaching (2021)',url:'https://pmc.ncbi.nlm.nih.gov/articles/PMC7900359/',note:'Supports carefully targeted teaching principles, not a claim that visual comparison games treat dyslexia or improve reading.'}];return '<ul class="sen-sources">'+sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a><p>${s.note}</p></li>`).join('')+'</ul>';}
function skillCourse(id){skillFreePlay=false;const{skill:s,course:c}=skillCourseGet(id);skillContext={skillId:s.id,courseId:id,index:null};prDirectLegacy=false;const done=c.activities.filter((a,i)=>skillExplored(a,id,i)).length,n=skillNotes[id]||{};const first=Math.max(0,c.activities.findIndex((a,i)=>!skillExplored(a,id,i)));app.innerHTML=`<div class="skill-crumb"><button class="back" id="skillCourseBack">← ${s.title}</button><span>GUIDED COURSE</span></div><section class="skill-course-hero"><div><span class="eyebrow">${s.title.toUpperCase()}</span><h1>${c.title}</h1><p class="skill-lead">${c.goal}</p><p><b>May be useful when:</b> ${c.need}</p><button class="primary" id="skillBegin">${done===c.activities.length?'Explore the course again':done?'Continue the course':'Start the first activity'} →</button><span class="micro">${c.activities.length} activities · ${done} explored · Stop or repeat whenever useful</span></div><div class="skill-course-preview" aria-hidden="true">${skillArt(c.activities[0])}</div></section><section class="skill-course-purpose"><div><h2>Try it together</h2><ol><li><b>Show one example.</b> Model the meaning before asking the child to respond.</li><li><b>Play with enough help.</b> Try a short activity. Keep reminders, help, and breaks available.</li><li><b>Use it in real life.</b> Try the everyday exercise below with different objects or pictures.</li></ol></div><div><h2>Have nearby</h2><p>${c.props}.</p><h3>What to notice</h3><ul>${c.notice.map(x=>`<li>${x}.</li>`).join('')}</ul><p class="micro">These are useful observations, not mastery criteria or diagnostic scores.</p></div></section><section class="skill-course-activities"><div class="section-head"><div><span class="eyebrow">A FLEXIBLE PATH THROUGH THE COURSE</span><h2>The activities</h2></div><span class="micro">Choose any starting point.</span></div><div class="skill-activity-list">${c.activities.map((a,i)=>`<button data-course-activity="${i}" class="skill-activity-row"><span class="skill-activity-number">${String(i+1).padStart(2,'0')}</span><span class="skill-activity-picture" aria-hidden="true">${skillArt(a)}</span><span><small>${i<Math.ceil(c.activities.length/3)?'BEGIN TOGETHER':i<Math.ceil(c.activities.length*2/3)?'BUILD WITH SUPPORT':'EXPLORE VARIETY'}</small><b>${skillTitle(a)}</b><span>${skillExplored(a,id,i)?'Explore again':'Open and play'} →</span></span></button>`).join('')}</div></section><section class="skill-real-life"><span class="eyebrow">THE PART THAT MATTERS AWAY FROM THE SCREEN</span><h2>Try this in everyday life</h2><p>${c.home}</p><button class="secondary" id="skillDownloadPlan">Save a practice plan ↓</button><label><input type="checkbox" id="skillOffline" ${n.offline?'checked':''}> We tried an everyday example together.</label></section><details class="skill-notes"><summary>Optional notes for next time</summary><p>Which support was useful? Keep it available; it does not need to be removed to count as learning.</p><div>${['An adult model','A visible reminder','Fewer choices / smaller steps','Help with controls or communication','A break or different time'].map((label,i)=>`<label><input type="checkbox" data-skill-note="${i}" ${n.supports?.includes(i)?'checked':''}> ${label}</label>`).join('')}</div><p class="micro">Saved in this browser, separately from earlier course progress. No name or diagnosis is collected.</p></details><details class="skill-notes"><summary>Evidence, adaptations & wider support</summary><p>These courses organise research-informed teaching principles into a practical sequence. Our app and course sequences have not been evaluated as interventions. Game improvement does not establish improvement in reading, ADHD symptoms, or everyday functioning. Individual language, sensory, vision, and motor needs may require adaptation.</p><p>Keep the child’s usual AAC and input support available. Do not delay appropriate language, communication, or reading instruction until courses are complete. Movement and breathing are optional; follow existing movement restrictions.</p>${skillEvidenceLinks(s)}<button class="secondary" id="skillEvidence">Read the research and support guidance →</button></details>`;skillNav();document.querySelector('#skillCourseBack').onclick=()=>skillDetail(s.id);document.querySelector('#skillBegin').onclick=()=>skillLaunch(id,first);document.querySelectorAll('[data-course-activity]').forEach(b=>b.onclick=()=>skillLaunch(id,+b.dataset.courseActivity));document.querySelector('#skillDownloadPlan').onclick=()=>skillDownloadPlan(id);document.querySelector('#skillOffline').onchange=e=>{skillNotes[id]??={};skillNotes[id].offline=e.target.checked;skillSave();};document.querySelectorAll('[data-skill-note]').forEach(input=>input.onchange=()=>{skillNotes[id]??={};skillNotes[id].supports=[...document.querySelectorAll('[data-skill-note]:checked')].map(e=>+e.dataset.skillNote);skillSave();});document.querySelector('#skillEvidence').onclick=()=>prParents('research');window.scrollTo(0,0);}
function skillDownloadPlan(id){const{skill,course:c}=skillCourseGet(id);const research=document.createElement('div');research.innerHTML=skillEvidenceLinks(skill);const lines=[c.title.toUpperCase(),'Skill: '+skill.title,'','WHEN THIS MAY BE USEFUL',c.need,'','OUR GOAL',c.goal,'','HAVE NEARBY',c.props,'','A GENTLE WAY TO BEGIN','1. Model one example in the child’s accessible language.','2. Try one small activity with enough help, reminders, breaks, and communication support.','3. Try the real-life exercise. Repeat, adapt, or stop according to the child.','','ACTIVITIES IN THIS COURSE',...c.activities.map((a,i)=>(i+1)+'. '+skillTitle(a)),'','TRY IT IN EVERYDAY LIFE',c.home,'','WHAT TO NOTICE',...c.notice.map(x=>'• '+x),'','These are practical observations, not diagnostic or mastery criteria. Game success does not establish everyday improvement.','','RESEARCH & GUIDANCE',...[...research.querySelectorAll('a')].map(a=>a.textContent+' — '+a.href),'','This is a research-informed educational plan, not an evaluated treatment or prescribed dose. Keep appropriate teaching, care, AAC, and established movement supports available. No child data is included in this card.'];const url=URL.createObjectURL(new Blob([lines.join('\n')+'\n'],{type:'text/plain;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download='practice-plan-'+c.id+'.txt';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function skillLaunch(courseId,index){const{skill,course}=skillCourseGet(courseId),a=course.activities[index];skillContext={skillId:skill.id,courseId,index};prDirectLegacy=true;prLibraryMode=false;if(a.engine==='playroom'){prStart(a.key);prDirectLegacy=true;}else if(a.engine==='original'){activeLearningCourse=a.key;if(a.key==='visual'){intro(a.index);document.querySelector('#begin')?.click();}else{learningIntro(a.index);(document.querySelector('#adultBegin')||document.querySelector('#learningBegin'))?.click();}}else if(a.engine==='support'){senActive=a.key;senIntro(a.index);document.querySelector('#senBegin')?.click();}else if(a.engine==='calm')calmOpen(a.index);else{focusIntro(a.index);document.querySelector('#focusOne')?.click();}skillDecorate();}
function skillDecorate(){if(prLibraryMode||!skillContext||skillContext.index===null)return;const{courseId,index}=skillContext,{course,skill}=skillCourseGet(courseId);skillNav();const back=document.querySelector('#prBack,#learningBack,#senBack,#focusBack,#calmBack,.play-top>.back');if(back){if(back.textContent!=='← Back to the course')back.textContent='← Back to the course';back.onclick=()=>skillCourse(courseId);}const completed=!!app.querySelector('#prReplay,#learningAgain,#adultAgain,#senAgain,#focusAgain,#calmAgain,.completion-stat');if(completed){skillNotes[courseId]??={};skillNotes[courseId].activities??={};if(!skillNotes[courseId].activities[index]){skillNotes[courseId].activities[index]=true;skillSave();}const parent=app.querySelector('.calm-controls,.game-controls,.sen-controls')||app.querySelector('section');if(parent&&!document.querySelector('#skillNextActivity')&&index<course.activities.length-1){const next=document.createElement('button');next.id='skillNextActivity';next.className='primary';next.textContent='Next course activity →';next.onclick=()=>skillLaunch(courseId,index+1);parent.append(next);}['prChoose','learningContinue','adultContinue','senAnother','focusReturn','calmReturn'].forEach(id=>{const b=document.getElementById(id);if(b){if(b.textContent!=='Back to the course')b.textContent='Back to the course';b.onclick=()=>skillCourse(courseId);}});}if(!app.querySelector('.skill-session-context')){const info=document.createElement('details');info.className='skill-session-context';info.innerHTML=`<summary>Course: ${course.title}</summary><p><b>Our goal:</b> ${course.goal}</p><p><b>Try it in daily life:</b> ${course.home}</p>`;app.append(info);}}
const skillsPreviousLibrary=libraryHome;
libraryHome=function(){if(prLibraryMode)skillsPreviousLibrary();else if(skillFreePlay)prHome();else skillHome();};
prHome=function(){if(skillFreePlay){skillOriginalFreePlay();history.replaceState(null,'',location.pathname+'?library=playroom');}else if(skillContext)skillCourse(skillContext.courseId);else skillHome();};
prNav=function(){skillNav();};
prTidyLegacy=function(){if(skillContext)skillDecorate();else{skillNav();const b=app.querySelector('.play-top>.back');if(b){b.textContent='← All skills';b.onclick=skillHome;}}};
// The observer also follows renders from the older course engines without replacing their logic.
new MutationObserver(()=>{if(skillContext&&skillContext.index!==null)skillDecorate();}).observe(app,{childList:true,subtree:true});

// Bookmarkable course routes and browser Back keep the adult-led path understandable.
let skillRestoringRoute=false;
function skillWriteRoute(type,id,index){if(skillRestoringRoute||prLibraryMode||skillFreePlay)return;const hash=type==='skills'?'#skills':type==='skill'?'#skill/'+id:type==='course'?'#course/'+id:'#activity/'+id+'/'+index;if(location.hash===hash)return;const state={skillRoute:hash,parentSkillHash:location.hash||null};if(!location.hash)history.replaceState(state,'',location.pathname+hash);else history.pushState(state,'',location.pathname+hash);}
const skillUnroutedHome=skillHome;skillHome=function(){skillUnroutedHome();skillWriteRoute('skills');};
const skillUnroutedDetail=skillDetail;skillDetail=function(id){skillUnroutedDetail(id);skillWriteRoute('skill',id);};
const skillUnroutedCourse=skillCourse;skillCourse=function(id){skillUnroutedCourse(id);skillWriteRoute('course',id);};
const skillUnroutedLaunch=skillLaunch;skillLaunch=function(id,index){skillUnroutedLaunch(id,index);skillWriteRoute('activity',id,index);};
function skillRestoreRoute(){if(prLibraryMode||skillFreePlay)return false;const parts=location.hash.slice(1).split('/');skillRestoringRoute=true;try{if(parts[0]==='skill'&&skillGet(parts[1]))skillDetail(parts[1]);else if(parts[0]==='course'&&learningSkills.some(s=>s.courses.some(c=>c.id===parts[1])))skillCourse(parts[1]);else if(parts[0]==='activity'&&learningSkills.some(s=>s.courses.some(c=>c.id===parts[1]))){const c=skillCourseGet(parts[1]).course,i=Number(parts[2]);if(Number.isInteger(i)&&i>=0&&i<c.activities.length)skillLaunch(c.id,i);else skillCourse(c.id);}else if(parts[0]==='skills')skillHome();else return false;return true;}finally{skillRestoringRoute=false;}}
window.addEventListener('popstate',()=>{const view=new URLSearchParams(location.search).get('library');prLibraryMode=view==='full';skillFreePlay=view==='playroom';if(prLibraryMode||skillFreePlay)libraryHome();else if(!skillRestoreRoute())skillHome();});

if(!skillRestoreRoute())libraryHome();
